content.content:
1	/* ===== Đoạn giới thiệu điện ảnh: bộ điều khiển (D-045) =====
2	   Phát ≈ 57 s trên chính cảnh 3D đang chạy (spec docs/superpowers/specs/2026-11-15-intro-dien-anh-design.md): dòng thời gian thuần (timeline.ts),
3	   chín nhịp (scenes.ts), lớp DOM (ui.ts). main.ts gọi intro.update(dt) ngay sau updateCamera(dt) và bỏ bước của bốn chế độ khi intro.hold.
4	   play() chụp trạng thái (camera, fov, near, controls, dayNight.target, chế độ Trực tiếp, show.on); cleanup() trả lại hết, gọi được nhiều lần
5	   (xong, Bỏ qua, nút hành động, lỗi). Cầu sông Hàn chưa về CLOSED thì "tiễn" trong update() tới khi đóng, cả sau khi intro đã kết thúc.
6	   Phím (pha capture trên window) chặn mọi phím khi intro chạy để không lọt xuống phím lái / Esc thoát (explore.exit tải lại trang).
7	   Không thêm gì vào cảnh; mỗi khung không cấp phát. */
8	import * as THREE from 'three';
9	import { camera, controls } from '../core/renderer';
10	import { onResize } from '../core/postprocessing';
11	import { dayNight } from '../core/dayNight';
12	import { show } from '../bridges/dragon/effects';
13	import { cam } from '../views/state';
14	import { drive } from '../explore/drive';
15	import { bike } from '../explore/bike';
16	import { stAvatars } from '../explore/stroll/avatars';
17	import { plPreload } from '../explore/pilot';
18	import { exRevealChooser, exHideChooser } from '../explore/chooser';
19	import { audio } from '../audio';
20	import { CONFIG } from '../config';
21	import { inCreate, inAdvance, inSeek, inFade, inFill, inShould, type InClock, type InSceneId } from './timeline';
22	import { inScenes, inScenesInit, inSee } from './scenes';
23	import { inUiSetup, inUiShow, inUiRender, inUiFill, inUiVeil, inUiPaused, inUiNoMore, inUiSound, type InActKind } from './ui';
24	import type { SwingController } from '../bridges/song-han/SwingController';
25	import type { LiveEnv } from '../realtime/liveEnv';
26	
27	export interface IntroDeps { ctrl: SwingController; live: LiveEnv | null }
28	
29	const I = CONFIG.intro, S = I.scenes, LAST = S.length - 1;
30	const clock: InClock = inCreate();
31	let deps: IntroDeps | null = null;
32	let active = false;
33	let cur = -1;                                  // nhịp đã enter() (−1: chưa / đã leave)
34	let waitMo: MutationObserver | null = null;    // play() khi #loading chưa done: chờ khung đầu
35	/* Trạng thái chụp lúc play(), trả ở cleanup() */
36	const snap = { pos: new THREE.Vector3(), target: new THREE.Vector3(), fov: 50, near: 0.5, enabled: true, maxPolar: Math.PI * 0.495, night: 0, wasLive: false, showOn: false };
37	
38	/* Bộ nhớ trình duyệt có thể bị chặn: mọi lần đọc / ghi bọc try */
39	const sget = (s: () => Storage, k: string): string | null => { try { return s().getItem(k); } catch { return null; } };
40	const sset = (s: () => Storage, k: string, v: string | null): void => { try { if (v === null) s().removeItem(k); else s().setItem(k, v); } catch { /* bộ nhớ bị chặn */ } };
41	const LS = () => localStorage, SS = () => sessionStorage;
42	
43	/* ---------- Nhạc nền trong intro: chỉ đọc audio.on và bấm hộ #btnMusic (cùng handler + lựa chọn đã lưu của audioUI.ts; bản nhạc nào cũng chạy đúng) ---------- */
44	const MUSIC_KEY = 'cauRong.music';                     // lựa chọn nhạc đã lưu ('on' | 'off'), audioUI.ts ghi
45	let touched = false;                                   // người xem đã thao tác trong lượt intro này (tắt gợi ý, chỉ tự bật một lần)
46	let noAuto = false;                                    // ?test: không tự bật nhạc
47	const clickMusic = (): void => { document.getElementById('btnMusic')?.click(); };
48	const syncSound = (): void => inUiSound(audio.on, !touched);
49	/* Thao tác đầu tiên của người xem: chờ một nhịp (bản nhạc khác có thể tự bật trước ở cùng thao tác) rồi nếu vẫn tắt và người xem chưa chọn tắt thì bấm hộ */
50	function musicNudge(): void {
51	  if (noAuto || audio.on || sget(LS, MUSIC_KEY) === 'off') return;
52	  setTimeout(() => { if (!audio.on && sget(LS, MUSIC_KEY) !== 'off') clickMusic(); syncSound(); }, 0);
53	}
54	function onFirstInput(e: Event): void {
55	  if (!active || touched) return;
56	  touched = true;
57	  const tg = e.target as Element | null;
58	  if (!(tg && tg.closest && tg.closest('#inSound'))) musicNudge();   // bấm chính nút nhạc: để nút tự bật / tắt, không bấm hộ
59	  syncSound();
60	}
61	
62	/* Đổi nhịp: leave() nhịp cũ → trạng thái nền của nhịp mới → enter(). jump: nhảy (nút, phím, bắt đầu) chứ không chạy tự nhiên từ nhịp trước ⇒ đặt luôn dayNight.night */
63	function enterScene(i: number, jump: boolean): void {
64	  if (cur >= 0) { const old = inScenes[S[cur].id]; cur = -1; old.leave(); }
65	  const id: InSceneId = S[i].id;
66	  const night = id === 'dragon' || id === 'swing' || id === 'finale' ? 1 : 0;   // welcome … daynight: ngày (daynight tự tăng trong update); ba nhịp cuối: đêm
67	  dayNight.target = night; if (jump) dayNight.night = night;
68	  if (show.on) { show.on = false; show.t = 0; }                                    // chỉ nhịp dragon bật trình diễn
69	  cam.flight.then = null; cam.mode = 'intro'; controls.enabled = false;            // nhịp chế độ đổi tiếp trong enter() (start())
70	  cur = i;
71	  inScenes[id].enter();
72	  inScenes[id].update(clock.t, 0);                                                 // đặt camera ngay (kể cả khi đang tạm dừng)
73	  inUiRender(i); syncSound();
74	  if (id === 'finale') (document.getElementById('inStart') as HTMLButtonElement | null)?.focus({ preventScroll: true });
75	}
76	
77	/* Lỗi trong một nhịp: ghi lại, dọn, hiện màn chọn. Trang không được kẹt ở intro */
78	function fail(e: unknown): void { console.warn('[intro] lỗi trong nhịp, dừng giới thiệu', e); intro.skip(); }
79	
80	/* Trả mọi thứ đã đổi; gọi nhiều lần an toàn */
81	function cleanup(): void {
82	  if (waitMo) { waitMo.disconnect(); waitMo = null; }
83	  if (!active) return;
84	  active = false;
85	  if (cur >= 0) { const old = inScenes[S[cur].id]; cur = -1; try { old.leave(); } catch (e) { console.warn('[intro] lỗi khi rời nhịp', e); } }
86	  const c = deps?.ctrl; if (c && c.state !== 'CLOSED') inSee.off = true;        // cầu còn mở / đang quay: tiễn về CLOSED trong update()
87	  if (show.on !== snap.showOn) { show.on = snap.showOn; show.t = 0; }
88	  const live = deps?.live;
89	  if (snap.wasLive && live) live.setMode('live', 'user');                         // Trực tiếp tự tính lại dayNight.target theo mặt trời thật
90	  else dayNight.target = snap.night;                                              // trời chuyển mượt bằng stepNight
91	  camera.position.copy(snap.pos); controls.target.copy(snap.target);
92	  if (camera.fov !== snap.fov || camera.near !== snap.near) { camera.fov = snap.fov; camera.near = snap.near; onResize(); }
93	  controls.maxPolarAngle = snap.maxPolar;
94	  cam.flight.then = null; cam.mode = 'orbit'; controls.enabled = snap.enabled;
95	  controls.update();
96	  clock.paused = false; inUiPaused(false);
97	  document.body.classList.remove('intro');
98	  inUiShow(false);
99	}
100	
101	/* Bắt đầu thật (sau khung đầu): chụp trạng thái, Mô phỏng, camera intro, lớp phủ, nhịp 0 */
102	function begin(): void {
103	  waitMo = null;
104	  if (active) return;
105	  /* mô hình nạp trước (chưa về thì chế độ dùng hình tạm có sẵn). Sau khung đầu, không sớm hơn: nạp trong lúc prewarm() (main.ts) chạy thì phần làm nóng
106	     shader của mô hình (compileAsync) chồng lên prewarm và three ném "reading 'isReady'" (thấy trên GPU thật, ?test&intro) */
107	  plPreload(); drive.preload(); bike.preload(); stAvatars.preload();
108	  snap.pos.copy(camera.position); snap.target.copy(controls.target);
109	  snap.fov = camera.fov; snap.near = camera.near; snap.enabled = controls.enabled; snap.maxPolar = controls.maxPolarAngle;
110	  snap.night = dayNight.target; snap.showOn = show.on;
111	  const live = deps?.live;
112	  snap.wasLive = !!live && live.mode === 'live';
113	  if (snap.wasLive) live!.setMode('manual', 'user');                              // trước: setMode ghi dayNight.target của Mô phỏng; intro ghi đè ngay sau
114	  dayNight.target = 0;
115	  cam.mode = 'intro'; controls.enabled = false; cam.flight.then = null;
116	  exHideChooser();
117	  document.body.classList.add('intro');
118	  active = true; touched = false;
119	  inSeek(clock, S, 0); clock.paused = false; inUiPaused(false);
120	  inUiNoMore(sget(LS, I.storeKey) === 'off');
121	  inUiShow(true);
122	  try { enterScene(0, true); } catch (e) { fail(e); }
123	}
124	
125	function go(i: number): void {
126	  if (!active) return;
127	  const n = inSeek(clock, S, i);
128	  if (clock.paused) { clock.paused = false; inUiPaused(false); }                  // nhảy nhịp là muốn xem: chạy tiếp (đang tạm dừng thì màn tối đầu nhịp sẽ đứng yên)
129	  try { enterScene(n, true); } catch (e) { fail(e); }
130	}
131	
132	/* Phím khi intro chạy (pha capture, trước mọi trình nghe khác trên window) */
133	function onKeyDown(e: KeyboardEvent): void {
134	  if (!active) return;
135	  if (e.ctrlKey || e.metaKey || e.altKey || e.key === 'Tab') return;
136	  const tg = e.target as HTMLElement | null;
137	  const inSel = !!tg && tg.id === 'inLang';
138	  if (inSel && (e.key.startsWith('Arrow') || e.key === 'Home' || e.key === 'End')) return;   // ô ngôn ngữ: mũi tên đổi lựa chọn như thường
139	  e.stopImmediatePropagation();
140	  const rtl = document.documentElement.dir === 'rtl';
141	  if (e.key === 'Escape') { e.preventDefault(); intro.skip(); }
142	  else if (e.key === ' ') { e.preventDefault(); if (!e.repeat) intro.pause(); }
143	  else if (e.key === 'ArrowRight') { e.preventDefault(); if (rtl) intro.prev(); else intro.next(); }
144	  else if (e.key === 'ArrowLeft') { e.preventDefault(); if (rtl) intro.next(); else intro.prev(); }
145	  else if (e.code === 'KeyM' || e.key === 'm' || e.key === 'M') { e.preventDefault(); if (!e.repeat) clickMusic(); syncSound(); }   // M = nút #inSound
146	  else if (e.key === 'Enter' && S[clock.i].id === 'finale' && !(tg && /^(BUTTON|SELECT|INPUT)$/.test(tg.tagName))) { e.preventDefault(); intro.skip(); }
147	}
148	function onKeyUp(e: KeyboardEvent): void {
149	  if (!active) return;
150	  if (e.ctrlKey || e.metaKey || e.altKey || e.key === 'Tab') return;
151	  e.stopImmediatePropagation();
152	  if (e.key === ' ') e.preventDefault();                                          // Space không bấm nút đang focus (đã dùng để tạm dừng)
153	}
154	
155	export const intro = {
156	  get active(): boolean { return active; },
157	  get hold(): boolean { return active && clock.paused; },
158	  get clock(): Readonly<InClock> { return clock; },
159	  get sceneId(): InSceneId | null { return active ? S[clock.i].id : null; },
160	  /* Gắn DOM, phím, nút #exIntroBtn / #btnIntro; gọi một lần */
161	  setup(d: IntroDeps): void {
162	    deps = d;
163	    inScenesInit(d.ctrl);
164	    inUiSetup({
165	      seek: (i) => go(i), prev: () => intro.prev(), next: () => intro.next(), pause: () => intro.pause(), skip: () => intro.skip(),
166	      act: (k) => intro.act(k), replay: () => go(0),
167	      noMore: (on) => sset(LS, I.storeKey, on ? 'off' : null)
168	    });
169	    noAuto = new URLSearchParams(location.search).has('test');
170	    window.addEventListener('pointerdown', onFirstInput, true);                     // trước onKeyDown: nó chặn mọi trình nghe sau trên window
171	    window.addEventListener('keydown', onFirstInput, true);
172	    document.getElementById('inSound')?.addEventListener('click', () => { clickMusic(); syncSound(); });
173	    window.addEventListener('keydown', onKeyDown, true);
174	    window.addEventListener('keyup', onKeyUp, true);
175	    document.getElementById('exIntroBtn')?.addEventListener('click', () => {
176	      intro.play();
177	      if (active && !touched) { touched = true; musicNudge(); syncSound(); }      // bấm "Xem giới thiệu" là thao tác của người xem: áp quy tắc tự bật ngay
178	    });
179	    document.getElementById('btnIntro')?.addEventListener('click', () => {
180	      sset(SS, I.playKey, '1');                                                    // trang mới đọc cờ này (wants) rồi phát; chép cách tải lại của explore.exit()
181	      const u = new URL(location.href);
182	      u.searchParams.delete('explore'); u.searchParams.delete('chooser'); u.searchParams.delete('intro');   // ?intro=off thắng cờ playKey (inShould) nên bỏ luôn
183	      if (u.href === location.href) location.reload(); else location.replace(u.toString());
184	    });
185	  },
186	  /* Có tự phát không (spec §5.1); đọc + xóa cờ playKey (nút "Xem giới thiệu" trong bảng Cài đặt) */
187	  wants(q: URLSearchParams): boolean {
188	    const forced = sget(SS, I.playKey) === '1';
189	    if (forced) sset(SS, I.playKey, null);
190	    let reduced = false;
191	    try { reduced = typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches; } catch { /* không có matchMedia */ }
192	    const conn = (navigator as Navigator & { connection?: { saveData?: boolean } }).connection;
193	    return inShould({ explore: q.has('explore'), test: q.has('test'), introParam: q.get('intro'), stored: sget(LS, I.storeKey), seen: sget(SS, I.seenKey) === '1', forced, reducedMotion: reduced, saveData: !!(conn && conn.saveData) });
194	  },
195	  /* Phát từ nhịp 0; chờ #loading.done nếu chưa có (như exRevealChooser); đang phát / đang chờ thì bỏ qua */
196	  play(): void {
197	    if (active || waitMo || !deps) return;
198	    sset(SS, I.seenKey, '1');
199	    const loading = document.getElementById('loading');
200	    if (!loading || loading.classList.contains('done')) { begin(); return; }
201	    const mo = new MutationObserver(() => { if (loading.classList.contains('done')) { mo.disconnect(); if (waitMo === mo) begin(); } });
202	    waitMo = mo;
203	    mo.observe(loading, { attributes: true, attributeFilter: ['class'] });
204	  },
205	  /* Mỗi khung, ngay sau updateCamera(dt): tiễn cầu, dòng thời gian, nhịp, màn tối, tiến trình */
206	  update(dt: number): void {
207	    if (inSee.off) {
208	      const c = deps?.ctrl;
209	      if (!c || c.state === 'CLOSED') inSee.off = false;
210	      else { c.speed = I.swingSpeed; if (c.state === 'OPEN') c.requestClose(); }
211	    }
212	    if (!active || clock.paused) return;
213	    try {
214	      const n = inAdvance(clock, S, dt);
215	      if (n >= 0) enterScene(n, false);
216	      if (cur >= 0) inScenes[S[cur].id].update(clock.t, dt);
217	    } catch (e) { fail(e); return; }
218	    if (!active) return;
219	    syncSound();                                                                   // chỉ ghi DOM khi audio.on đổi (ui.ts nhớ giá trị đã ghi)
220	    const i = clock.i;
221	    inUiVeil(inFade(clock.t, S[i].dur, I.fade, i === 0, i === LAST));
222	    inUiFill(i, inFill(clock, S, i));
223	  },
224	  seek(i: number): void { go(i); },
225	  next(): void { if (active) go(Math.min(LAST, clock.i + 1)); },
226	  prev(): void { if (active) go(Math.max(0, clock.i - 1)); },
227	  pause(on?: boolean): void {
228	    if (!active) return;
229	    clock.paused = on === undefined ? !clock.paused : on;
230	    inUiPaused(clock.paused);
231	  },
232	  /* Kết thúc intro, hiện màn chọn */
233	  skip(): void { cleanup(); exRevealChooser(); },
234	  /* Nút hành động (spec §5.2): kết thúc, hiện màn chọn rồi bấm hộ đúng phần tử có sẵn */
235	  act(kind: InActKind): void {
236	    const c = deps?.ctrl;
237	    const busy = kind === 'swing' && !!c && c.state !== 'CLOSED';
238	    cleanup();
239	    if (busy) inSee.off = false;                                                   // "Xem cầu quay" khi cầu đang quay: để cầu quay tiếp, không tiễn
240	    exRevealChooser();
241	    const click = (sel: string) => (document.querySelector(sel) as HTMLElement | null)?.click();
242	    if (kind === 'glider' || kind === 'car' || kind === 'bike' || kind === 'walk') { click(`button[data-pick="${kind}"]`); return; }
243	    click('button[data-pick="guided"]');
244	    if (kind === 'tour') click('[data-view="allTour"]');
245	    else if (kind === 'dragon') {
246	      click('[data-bridge="dragon"]'); click('[data-view="head"]');
247	      const b = document.getElementById('btnShow'); if (b && b.getAttribute('aria-pressed') !== 'true') b.click();
248	    } else if (kind === 'swing') {
249	      click('[data-bridge="sh"]');
250	      if (!busy) document.getElementById('btnSwing')?.click();
251	    }
252	  }
253	};
254

