const only = (process.argv[2] || 'a,c1,c2,c3,c4,c5').split(',');
const sleep = (ms) => new Promise((ok) => setTimeout(ok, ms));
const problems = [];
const check = (n, ok, extra = '') => { if (!ok) problems.push(n); console.log(`${ok ? 'đạt ' : 'LỖI '} ${n} ${extra}`); };
const fixture = fs.readFileSync(ROOT + 'tests/env-unit/fixture.json', 'utf8');
const srv = await serveDir(ROOT + 'dist');
const browser = await launch();

/* Trang không ?test: chặn Open-Meteo (fixture), GTM, font; ghi lỗi console */
async function openPlain(path, { init = null, glbBlock = false } = {}) {
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on('pageerror', (e) => errors.push('pageerror: ' + String(e)));
  page.on('console', (m) => { if (m.type() === 'error' && !/fonts\.(googleapis|gstatic)|ERR_FAILED|net::|googletagmanager|open-meteo/.test(m.text())) errors.push(m.text()); });
  await page.route(/fonts\.(googleapis|gstatic)\.com/, (r) => r.abort());
  await page.route(/googletagmanager\.com/, (r) => r.abort());
  await page.route(/api\.open-meteo\.com/, (r) => r.fulfill({ status: 200, contentType: 'application/json', body: fixture }));
  if (glbBlock) await page.route(/\.glb(\?|$)/, (r) => r.abort());
  if (init) await page.addInitScript(init);
  await page.goto(srv.url + path, { waitUntil: 'load', timeout: 180000 });
  await page.waitForFunction(() => document.getElementById('loading')?.classList.contains('done'), null, { timeout: 180000 });
  return { page, errors };
}
